def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    opp_c = op.count('C')
    opp_d = n - opp_c
    my_d = my.count('D')

    last_op = op[-1]

    # Track opponent defection streak
    op_def_streak = 0
    for a in reversed(op):
        if a == 'D':
            op_def_streak += 1
        else:
            break

    # Track opponent cooperation streak
    op_c_streak = 0
    for a in reversed(op):
        if a == 'C':
            op_c_streak += 1
        else:
            break

    # Recent window analysis
    w = min(15, n)
    recent = op[-w:]
    recent_c = recent.count('C')
    recent_rate = recent_c / w

    # Endgame phase
    remaining = 100 - n

    # If opponent never defected, cooperate until very end, then defect
    if opp_d == 0:
        if remaining <= 2:
            return 'D'
        return 'C'

    # Opponent mostly cooperative (few defections)
    if opp_d <= 2 and opp_c >= n - 2:
        if last_op == 'D':
            return 'D'
        if remaining <= 3:
            return 'D'
        return 'C'

    # Opponent is a heavy defector: punish but probe occasionally
    if opp_d > opp_c + 3 or recent_rate < 0.25:
        # If we've been cooperating a lot and they keep defecting, stay in D
        if last_op == 'D':
            if op_def_streak >= 4 and rng.random() < 0.05:
                return 'C'
            return 'D'
        # Opponent just cooperated after long defection — test cooperation
        if op_c_streak >= 1 and rng.random() < 0.6:
            return 'C'
        return 'D'

    # Mutually stuck in defection: try to break the cycle
    if last_op == 'D' and op_def_streak >= 3:
        if rng.random() < 0.2:
            return 'C'
        return 'D'

    # Opponent just defected
    if last_op == 'D':
        # Isolated defection from a mostly-cooperative opponent: forgive
        if opp_d == 1:
            return 'C'
        if recent_rate >= 0.7:
            return 'C'
        # Otherwise retaliate
        return 'D'

    # Opponent just cooperated
    # If we've been defecting more than them, return to cooperation
    if my_d > opp_d + 3:
        return 'C'

    # Late-game exploitation of moderately exploitable opponents
    if remaining <= 4 and recent_rate >= 0.6:
        return 'D'

    return 'C'
